        {% for m in models %}
          <option value="{{ m.pk }}" {% if m.pk == conversation.model_id %}selected{% endif %}>{{ m.display_name }} · {{ m.get_provider_display }} · ${{ m.input_price_micros_per_mtok|price_per_mtok }}/${{ m.output_price_micros_per_mtok|price_per_mtok }} per 1M tok</option>
        {% endfor %}
      </select>
      <textarea name="content" id="content" rows="2" placeholder="Message" required></textarea>
      <button id="send">Send</button>
    </form>
  {% endif %}
  </section>
</div>

{% if conversation %}
