import json, sys, collections
types = collections.Counter(); ctypes = collections.Counter()
ex = {}
for line in open(sys.argv[1]):
    try: o = json.loads(line)
    except ValueError: continue
    t = o.get("type"); types[t] += 1
    m = o.get("message")
    if isinstance(m, dict):
        c = m.get("content")
        if isinstance(c, str): ctypes[(t, "str")] += 1; ex.setdefault((t, "str"), c[:80])
        elif isinstance(c, list):
            for b in c:
                k = (t, b.get("type")); ctypes[k] += 1
                ex.setdefault(k, json.dumps(b)[:160])
print(types); print(ctypes)
for k, v in ex.items(): print(k, "=>", v)
